contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function taking parameters that drive C.transfer
    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        require(_tos.length > 0);
        require(_tos.length == v.length);

        // observe balance of c before
        uint before = address(c).balance;

        bool reverted;
        bool returned;
        // perform the call and capture whether it reverted and if it returned true
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            returned = r;
        } catch {
            reverted = true;
            returned = false;
        }

        // The general rule: transfer never returns false; it either reverts or returns true.
        // Also assert that a successful call does not change c's ETH balance (C.transfer contains no payable logic).
        assert((reverted || returned == true) && (reverted || address(c).balance == before));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        require(_tos.length > 0);
        require(_tos.length == v.length);

        uint before = address(c).balance;
        bool reverted;
        bool ok;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ok = r;
        } catch {
            reverted = true;
            ok = false;
        }

        // General rule: either reverted, or returned true, and if not reverted the balance is unchanged
        assert(reverted || (ok && address(c).balance == before));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        require(_tos.length > 0);
        require(_tos.length == v.length);

        bool reverted;
        bool returnedTrue = false;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            returnedTrue = r;
        } catch {
            reverted = true;
        }

        // General rule: either the call reverted, or it returned true (it never returns false)
        assert(reverted || returnedTrue);
    }

    receive() external payable {}
}
